import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // reads ANTHROPIC_API_KEY; server side only
const MODEL = process.env.LLM_MODEL!; // pin the model ID in config, not in code

export async function summarise(text: string): Promise<string> {
  const res = await client.messages.create({
    model: MODEL,
    max_tokens: 1024, // hard cap on output: bounds cost and latency
    system: "Summarise the text inside <text> in under 120 words.",
    messages: [{ role: "user", content: `<text>\n${text}\n</text>` }],
  });

  // Log real token counts from the response, never estimates.
  const { input_tokens, output_tokens } = res.usage;
  console.log(JSON.stringify({ model: MODEL, input_tokens, output_tokens, stop: res.stop_reason }));

  // "max_tokens" = the answer was cut off. Never treat it as complete.
  if (res.stop_reason === "max_tokens") throw new Error("LLM output truncated");
  if (res.stop_reason === "refusal") throw new Error("LLM refused");

  return res.content
    .filter((b) => b.type === "text")
    .map((b) => b.text)
    .join("");
}

export async function reply(history: Anthropic.MessageParam[]) {
  const res = await client.messages.create({
    model: MODEL,
    max_tokens: 300,
    messages: history,
  });
  const text = res.content
    .filter((b) => b.type === "text")
    .map((b) => b.text)
    .join("");
  history.push({ role: "assistant", content: text });
  return text;
}

