import Anthropic from "@anthropic-ai/sdk";
import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
import { z } from "zod";

// Enums instead of free strings. The SDK helper moves enum values and
// min/max into the field description (the grammar does not enforce them),
// then Zod checks them after parsing and parse() throws on a mismatch.
const Ticket = z.object({
  category: z.enum(["billing", "bug", "account", "other"]),
  urgency: z.enum(["low", "normal", "high"]),
  summary: z.string(),
});
type Ticket = z.infer<typeof Ticket>;

const FALLBACK: Ticket = { category: "other", urgency: "normal", summary: "[needs human review]" };
const client = new Anthropic();

export async function classify(text: string): Promise<Ticket> {
  let res;
  try {
    res = await client.messages.parse({
      model: process.env.LLM_MODEL!,
      max_tokens: 512,
      system: "Classify the support ticket inside <ticket>. Use 'other' when unsure.",
      messages: [{ role: "user", content: `<ticket>\n${text}\n</ticket>` }],
      output_config: { format: zodOutputFormat(Ticket) },
    });
  } catch (err) {
    // parse() THROWS when the text is not valid for the schema: JSON cut off by
    // max_tokens, a refusal written as text, or a value Zod rejects.
    // API errors (429, 500, network) are APIError: let retries/alerts see them.
    if (err instanceof Anthropic.APIError || !(err instanceof Anthropic.AnthropicError)) throw err;
    return FALLBACK;
  }

  // Refusal with no text block: parsed_output is null.
  if (res.stop_reason !== "end_turn" || !res.parsed_output) return FALLBACK;

  // Valid shape is not the same as a correct value: business checks still apply.
  return res.parsed_output;
}

