const tools: Anthropic.Tool[] = [{
  name: "get_order",
  description: "Get one of the CURRENT user's orders by number. Returns status and tracking number.",
  input_schema: {
    type: "object",
    properties: { order_id: { type: "integer" } },
    required: ["order_id"],
    additionalProperties: false,
  },
  strict: true, // arguments are guaranteed to match the schema
}];

async function runTool(name: string, input: unknown, user: User): Promise<string> {
  if (name !== "get_order") throw new Error(`Unknown tool: ${name}`);
  const { order_id } = z.object({ order_id: z.number().int() }).parse(input);
  // Authorise as the end user: the WHERE clause is the security boundary.
  const order = await db.order.findFirst({ where: { id: order_id, userId: user.id } });
  if (!order) return "No order with that number for this user.";
  return JSON.stringify({ status: order.status, tracking: order.trackingNo }); // small result
}

export async function chat(user: User, messages: Anthropic.MessageParam[]) {
  for (let step = 0; step < 5; step++) { // hard cap on tool rounds
    const res = await client.messages.create({ model: MODEL, max_tokens: 1024, tools, messages });
    messages.push({ role: "assistant", content: res.content });
    if (res.stop_reason !== "tool_use") return res;

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of res.content) {
      if (block.type !== "tool_use") continue;
      try {
        const content = await runTool(block.name, block.input, user);
        results.push({ type: "tool_result", tool_use_id: block.id, content });
      } catch (err) {
        results.push({ type: "tool_result", tool_use_id: block.id, content: String(err), is_error: true });
      }
    }
    messages.push({ role: "user", content: results }); // ALL results in ONE user message
  }
  throw new Error("Tool loop hit 5 rounds");
}

