type Policy = { maxSteps: number; maxCostUsd: number; maxWallMs: number };
const NEEDS_APPROVAL = new Set(["issue_refund", "send_email"]);

export async function runAgent(goal: string, run: RunContext, p: Policy) {
  const started = Date.now();
  let costUsd = 0;
  const messages: Anthropic.MessageParam[] = [{ role: "user", content: goal }];

  for (let step = 1; step <= p.maxSteps; step++) {
    if (Date.now() - started > p.maxWallMs) return run.stop("timeout", step);

    const res = await client.messages.create({ model: MODEL, max_tokens: 2048, system: AGENT_SYSTEM, tools, messages });
    costUsd += priceOf(MODEL, res.usage); // input + output + cache tokens
    await run.trace({ step, stop: res.stop_reason, usage: res.usage, content: res.content });
    if (costUsd > p.maxCostUsd) return run.stop("budget", step);

    messages.push({ role: "assistant", content: res.content });
    if (res.stop_reason !== "tool_use") return run.finish(res);

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const call of res.content.filter((b) => b.type === "tool_use")) {
      if (NEEDS_APPROVAL.has(call.name)) {
        await run.checkpoint(messages); // durable state: survives a restart while waiting
        const approved = await run.askHuman(call.name, call.input);
        if (!approved) {
          results.push({ type: "tool_result", tool_use_id: call.id, content: "The user declined this action.", is_error: true });
          continue;
        }
      }
      results.push({ type: "tool_result", tool_use_id: call.id, content: await run.exec(call.name, call.input) });
    }
    messages.push({ role: "user", content: results });
  }
  return run.stop("max_steps", p.maxSteps);
}

