// evals/run.ts — run in CI on every prompt, model or retrieval change: npx tsx evals/run.ts
import cases from "./ticket-cases.json" with { type: "json" };
import { classify } from "../src/classify";

type Case = { id: string; slice: string; input: string; expected: string };
const MIN_PER_SLICE = 0.88; // gate on the worst slice, not the average

const bySlice = new Map<string, { pass: number; total: number; fails: string[] }>();
for (const c of cases as Case[]) {
  const s = bySlice.get(c.slice) ?? { pass: 0, total: 0, fails: [] };
  const out = await classify(c.input); // the real prompt + model under test
  s.total++;
  if (out.category === c.expected) s.pass++;
  else s.fails.push(`${c.id}: expected ${c.expected}, got ${out.category}`);
  bySlice.set(c.slice, s);
}

let ok = true;
for (const [slice, s] of bySlice) {
  const rate = s.pass / s.total;
  console.log(`${slice.padEnd(10)} ${(rate * 100).toFixed(1)}%  (${s.pass}/${s.total})`);
  for (const f of s.fails.slice(0, 5)) console.log("   FAIL", f); // read failures, not just scores
  if (rate < MIN_PER_SLICE) ok = false;
}
process.exit(ok ? 0 : 1);

