// app/api/ask/route.ts (Next.js 16 route handler, Node runtime)
import Anthropic from "@anthropic-ai/sdk";
import { INSTRUCTIONS } from "@/prompts/support"; // ~6k tokens, identical every call

const client = new Anthropic({ maxRetries: 2, timeout: 60_000 }); // TS SDK timeout is in ms

export async function POST(req: Request) {
  const { userId, question } = await authAndParse(req);
  if (await overDailyTokenBudget(userId)) return new Response("Daily AI limit reached", { status: 429 });

  const stream = client.messages.stream(
    {
      model: process.env.LLM_MODEL!,
      max_tokens: 800,
      // Stable prefix first, marked for caching; the question comes after it.
      system: [{ type: "text", text: INSTRUCTIONS, cache_control: { type: "ephemeral" } }],
      messages: [{ role: "user", content: question }],
    },
    { signal: req.signal }, // user closed the tab: stop generating (and paying)
  );

  const enc = new TextEncoder();
  const body = new ReadableStream({
    async start(controller) {
      stream.on("text", (t) => controller.enqueue(enc.encode(`data: ${JSON.stringify(t)}\n\n`)));
      try {
        await stream.finalMessage();
      } catch {
        if (!req.signal.aborted) controller.enqueue(enc.encode(`event: error\ndata: "AI is busy, please retry"\n\n`));
      } finally {
        // Record what was really generated, even when the user aborted mid-answer:
        // otherwise stopping early would dodge the daily quota.
        const usage = stream.currentMessage?.usage; // input_tokens, output_tokens, cache_* tokens
        if (usage) await recordUsage(userId, usage);
        controller.close();
      }
    },
  });
  return new Response(body, { headers: { "Content-Type": "text/event-stream", "Cache-Control": "no-cache" } });
}

export function costUsd(u: Anthropic.Usage, p: Price): number {
  return (
    (u.input_tokens * p.inputPerMTok + u.output_tokens * p.outputPerMTok) / 1e6
  );
}

