// Remote MCP server, @modelcontextprotocol/server v2, web-standard runtime (Workers, Deno, Bun)
import {
  createMcpHandler, getOAuthProtectedResourceMetadataUrl, hostHeaderValidationResponse,
  McpServer, OAuthError, OAuthErrorCode, requireBearerAuth, type AuthInfo,
} from "@modelcontextprotocol/server";
import * as z from "zod/v4";

const RESOURCE = "https://mcp.acme.com/mcp"; // canonical URI = the audience tokens must carry
type Claims = { azp: string; scope: string; exp: number; sub: string };

async function verifyAccessToken(token: string): Promise<AuthInfo> {
  let c: Claims;
  try {
    c = await verifyJwt(token, { audience: RESOURCE }); // signature, expiry AND audience
  } catch {
    // Must be an OAuthError: the SDK turns it into 401 + WWW-Authenticate.
    // Any other error becomes a 500, and the client never starts the login flow.
    throw new OAuthError(OAuthErrorCode.InvalidToken, "Invalid or expired token");
  }
  return { token, clientId: c.azp, scopes: c.scope.split(" "), expiresAt: c.exp, extra: { accountId: c.sub } };
}

const handler = createMcpHandler(() => {
  const server = new McpServer({ name: "acme-invoices", version: "1.0.0" });
  server.registerTool(
    "list_invoices",
    {
      description: "List the signed-in customer's invoices, newest first, max 20. Filter by status.",
      inputSchema: z.object({ status: z.enum(["open", "paid", "overdue"]).optional() }),
      annotations: { readOnlyHint: true }, // a hint for the client UI, not security
    },
    async ({ status }, ctx) => {
      const accountId = ctx.http?.authInfo?.extra?.accountId;
      if (typeof accountId !== "string") return { content: [{ type: "text", text: "Not signed in." }], isError: true };
      // Scope by the verified token, never by an argument the model chose.
      const rows = await db.invoice.findMany({ where: { accountId, ...(status && { status }) }, take: 20 });
      return { content: [{ type: "text", text: JSON.stringify(rows) }] };
    },
  );
  return server;
});

const gate = requireBearerAuth({
  verifier: { verifyAccessToken },
  requiredScopes: ["invoices:read"],
  // Advertised in the 401 challenge so clients can discover the authorization server.
  resourceMetadataUrl: getOAuthProtectedResourceMetadataUrl(new URL(RESOURCE)),
});

export default {
  async fetch(request: Request): Promise<Response> {
    const badHost = hostHeaderValidationResponse(request, ["mcp.acme.com"]); // DNS-rebinding guard
    if (badHost) return badHost;
    const auth = await gate(request); // AuthInfo, or a ready 401/403 Response
    if (auth instanceof Response) return auth;
    return handler.fetch(request, { authInfo: auth });
  },
};

const gate = requireBearerAuth({
  verifier: {
    async verifyAccessToken(token) {
      const c = await verifyJwt(token, { audience: RESOURCE });
      // verifyJwt throws Error("jwt expired") for old tokens
      return { token, clientId: c.azp, scopes: c.scope.split(" "), expiresAt: c.exp };
    },
  },
  requiredScopes: ["invoices:read"],
});
